def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Aggregate counts in a single pass
    my_c = my_d = op_c = op_d = 0
    cc = cd = dc = dd = 0
    for my, op in history:
        if my == 'C':
            my_c += 1
        else:
            my_d += 1
        if op == 'C':
            op_c += 1
        else:
            op_d += 1
        if my == 'C':
            if op == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if op == 'C':
                dc += 1
            else:
                dd += 1

    last_my, last_op = history[-1]

    # Recent window stats
    w = 8 if n >= 8 else n
    recent_op_c = 0
    recent_op_d = 0
    recent_my_d = 0
    for i in range(n - w, n):
        mo, oo = history[i]
        if oo == 'C':
            recent_op_c += 1
        else:
            recent_op_d += 1
        if mo == 'D':
            recent_my_d += 1

    # Consecutive opponent defections at end
    consec_op_d = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            consec_op_d += 1
        else:
            break

    # Consecutive opponent cooperations at end
    consec_op_c = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            consec_op_c += 1
        else:
            break

    # Consecutive mutual defections at end
    consec_dd = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D' and history[i][1] == 'D':
            consec_dd += 1
        else:
            break

    op_coop_rate = op_c / n

    # --- Opening: cooperate to establish mutual cooperation ---
    if n < 4:
        return 'C'

    remaining = 100 - n

    # --- Endgame: exploit cooperators, don't get suckered ---
    if remaining <= 3:
        if op_coop_rate >= 0.5 or consec_op_c >= 1:
            return 'D'
        return 'D'

    if remaining <= 8:
        # Last stretch: defect against cooperative opponents
        if op_coop_rate >= 0.55:
            return 'D'
        if consec_op_c >= 1 and op_coop_rate >= 0.4:
            return 'D'
        if last_op == 'D':
            return 'D'
        return 'C'

    # --- Identify pure/near-pure opponents ---
    if n >= 5 and op_coop_rate <= 0.1:
        # Opponent almost always defects: defect, rare probe
        if n % 13 == 0:
            return 'C'
        return 'D'

    if n >= 10 and op_coop_rate >= 0.95:
        # Pure cooperator -> exploit more aggressively but keep gains high
        # Alternate so they don't retaliate; they won't anyway.
        if n % 3 == 0:
            return 'D'
        return 'C'

    # --- Punish long opponent defection streaks ---
    if consec_op_d >= 4:
        if n % 9 == 0:
            return 'C'
        return 'D'

    # --- Break mutual defection death spirals ---
    if consec_dd >= 3:
        # Cooperative gesture to escape
        if rng.random() < 0.4:
            return 'C'
        return 'D'

    # --- Main reciprocal core ---
    if last_op == 'C':
        # Occasionally probe a highly-cooperative opponent for extra gain
        if op_coop_rate >= 0.75 and consec_op_c >= 3:
            if rng.random() < 0.06:
                return 'D'
        return 'C'

    # Opponent defected last round
    # If opponent is mostly cooperative, forgive sometimes to rebuild
    if op_coop_rate >= 0.7:
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    if op_coop_rate >= 0.5:
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Mostly defecting opponent: retaliate
    if n % 11 == 0:
        return 'C'
    return 'D'
